def clear_existing_data():
    """Clear existing data to replace with diverse dataset"""
    db = DatabaseManager()
    # Get count of existing QA pairs before clearing
    existing_pairs = db.get_qa_pairs()
    existing_count = len(existing_pairs)

    # Clear all data using the built-in method
    db.clear_database()
    print(f"Cleared {existing_count} existing QA pairs")
    return db

